-- Cue snapshots, derived counts, immutable history and current-design playback.
select no_plan();
select tests.create_range_fixture();
select is((select quantity from public.show_version_products where organisation_id = '10000000-0000-0000-0000-000000000001'),1::smallint,'quantity is derived from cues');
reset role;
select tests.act_as('organisation_owner');
select lives_ok($test$select public.save_show('93000000-0000-0000-0000-000000000001',tests.show_cues() || tests.show_cues(),6000)$test$,'owner saves complete snapshot');
select is((select max(number) from public.show_versions),2,'save numbers versions under parent lock');
select is((select quantity from public.show_version_products where show_version_id = (select current_version_id from public.shows where id = '93000000-0000-0000-0000-000000000001')),2::smallint,'save counts repeated products');
select is((select price_minor from public.show_store_status where show_id = '93000000-0000-0000-0000-000000000001'),5000::numeric,'show total is current price times quantity');
select throws_ok($test$select public.save_show('93000000-0000-0000-0000-000000000001','[]',6000)$test$,'23514',null,'empty cues rejected');
select throws_ok($test$select public.save_show('93000000-0000-0000-0000-000000000001','[{"t_ms":-1}]',6000)$test$,'23514',null,'invalid cue shape rejected');
select throws_ok($test$select public.save_show('93000000-0000-0000-0000-000000000001',tests.show_cues('60000000-0000-0000-0000-000000000002'),6000)$test$,'23514',null,'draft product rejected');
select throws_ok($test$select public.save_show('93000000-0000-0000-0000-000000000001',tests.show_cues('60000000-0000-0000-0000-000000000003'),6000)$test$,'23514',null,'product outside retailer range rejected');
select throws_ok($test$select public.save_show('93000000-0000-0000-0000-000000000002',tests.show_cues(),6000)$test$,'42501',null,'foreign retailer show save denied');
select is((select count(*) from public.show_versions),2::bigint,'failed saves leave history unchanged');
select throws_ok($test$update public.shows set current_version_id = null$test$,'42501',null,'caller cannot edit derived current pointer');
reset role;
select tests.act_as('anonymous_shopper');
select lives_ok($test$insert into public.shows(id,owner_id,name,origin) values ('93000000-0000-0000-0000-000000000004',auth.uid(),'Anonymous private show','manual')$test$,'anonymous shopper creates own show');
select lives_ok($test$select public.save_show('93000000-0000-0000-0000-000000000004',tests.show_cues(),6000)$test$,'anonymous shopper saves own snapshot');
select throws_ok($test$select public.save_show('93000000-0000-0000-0000-000000000003',tests.show_cues(),6000)$test$,'42501',null,'anonymous shopper cannot save another shopper show');
reset role;
select tests.act_as('signed_in_shopper');
select lives_ok($test$select public.save_show('93000000-0000-0000-0000-000000000003',tests.show_cues(),6000)$test$,'signed-in shopper saves own snapshot');
select ok(public.show_for_store('93000000-0000-0000-0000-000000000003','90000000-0000-0000-0000-000000000001') is not null,'shopper can play their own saved show at a visible store');
select throws_ok($test$insert into public.shows(owner_id,name,origin) values (tests.get_supabase_uid('organisation_owner'),'Foreign private show','manual')$test$,'42501',null,'shopper cannot assign another owner');
reset role;
set local role service_role;
select throws_ok($test$update public.show_versions set cues = '[]'$test$,'23514',null,'service cannot rewrite versions');
select throws_ok('delete from public.show_versions','23514',null,'service cannot delete versions');
select throws_ok('update public.show_version_products set quantity = 5','23514',null,'service cannot rewrite quantities');
select throws_ok('delete from public.show_version_products','23514',null,'service cannot delete quantities');
reset role;
select finish();
